Here is the commit message:
wwan: core: Fix missing RTM_NEWLINK event for default link

A wwan link created via the wwan_create_default_link procedure is
never notified to the user (RTM_NEWLINK), causing issues with user
tools relying on such event to track network links (NetworkManager).

This is because the procedure misses a call to rtnl_configure_link(),
which sets the link as initialized and notifies the new link (cf
proper usage in __rtnl_newlink()).

Cc: stable@vger.kernel.org
Fixes: ca374290aaad ("wwan: core: support default netdev creation")
Suggested-by: Sergey Ryazanov <ryazanov.s.a@gmail.com>
Signed-off-by: Loic Poulain <loic.poulain@linaro.org>
Acked-by: Sergey Ryazanov <ryazanov.s.a@gmail.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was caused by the absence of a call to `rtnl_configure_link()` in the `wwan_create_default_link` function, which prevented the link from being marked as initialized and did not notify user-space applications of the new link creation (RTM_NEWLINK event). This oversight led to issues with user tools that rely on such notifications to track network links.

Here is the patch:

 static void wwan_create_default_link(struct wwan_device *wwandev,
 				     u32 def_link_id)
 {
 	struct nlattr *tb[IFLA_MAX + 1], *linkinfo[IFLA_INFO_MAX + 1];
 	struct nlattr *data[IFLA_WWAN_MAX + 1];
 	struct net_device *dev;
 	struct nlmsghdr *nlh;
 	struct sk_buff *msg;

 	/* Forge attributes required to create a WWAN netdev. We first
 	 * build a netlink message and then parse it. This looks
 	 * odd, but such approach is less error prone.
 	 */
 	msg = nlmsg_new(NLMSG_DEFAULT_SIZE, GFP_KERNEL);
 	if (WARN_ON(!msg))
 		return;
 	nlh = nlmsg_put(msg, 0, 0, RTM_NEWLINK, 0, 0);
 	if (WARN_ON(!nlh))
 		goto free_attrs;

 	if (nla_put_string(msg, IFLA_PARENT_DEV_NAME, dev_name(&wwandev->dev)))
 		goto free_attrs;
 	tb[IFLA_LINKINFO] = nla_nest_start(msg, IFLA_LINKINFO);
 	if (!tb[IFLA_LINKINFO])
 		goto free_attrs;
 	linkinfo[IFLA_INFO_DATA] = nla_nest_start(msg, IFLA_INFO_DATA);
 	if (!linkinfo[IFLA_INFO_DATA])
 		goto free_attrs;
 	if (nla_put_u32(msg, IFLA_WWAN_LINK_ID, def_link_id))
 		goto free_attrs;
 	nla_nest_end(msg, linkinfo[IFLA_INFO_DATA]);
 	nla_nest_end(msg, tb[IFLA_LINKINFO]);

 	nlmsg_end(msg, nlh);

 	/* The next three parsing calls can not fail */
 	nlmsg_parse_deprecated(nlh, 0, tb, IFLA_MAX, NULL, NULL);
 	nla_parse_nested_deprecated(linkinfo, IFLA_INFO_MAX, tb[IFLA_LINKINFO],
 				    NULL, NULL);
 	nla_parse_nested_deprecated(data, IFLA_WWAN_MAX,
 				    linkinfo[IFLA_INFO_DATA], NULL, NULL);

 	rtnl_lock();

 	dev = rtnl_create_link(&init_net, "wwan%d", NET_NAME_ENUM,
 			       &wwan_rtnl_link_ops, tb, NULL);
 	if (WARN_ON(IS_ERR(dev)))
 		goto unlock;

 	if (WARN_ON(wwan_rtnl_newlink(&init_net, dev, tb, data, NULL))) {
 		free_netdev(dev);
 		goto unlock;
 	}

+	rtnl_configure_link(dev, NULL); /* Link initialized, notify new link */
+
 unlock:
 	rtnl_unlock();

 free_attrs:
 	nlmsg_free(msg);
 }



